mapper.select:
SELECT COALESCE(SUM(r.good_qty), 0) AS "good", COALESCE(SUM(r.scrap_qty), 0) AS "scrap", COALESCE(SUM(r.hours), 0) AS "hours"
FROM mes_report r
JOIN mes_wo_op o ON o.id = r.op_id
WHERE r.report_date >= #{begin} AND r.report_date <= #{end}
AND o.work_center_id = #{wc}

SELECT COALESCE(SUM(total_amount), 0) AS "amount", COUNT(*) AS "orders"
FROM scm_order
WHERE kind = 'SALES' AND status IN ('APPROVED', 'PARTIAL', 'COMPLETED') AND order_date >= #{begin} AND order_date <= #{end}

SELECT COALESCE(SUM(CASE WHEN kind = 'SALES_OUT' THEN total_amount ELSE -total_amount END), 0)
FROM scm_trade_doc
WHERE kind IN ('SALES_OUT', 'SALES_RETURN') AND biz_date >= #{begin} AND biz_date <= #{end}

SELECT COALESCE(SUM(t.amount), 0) FROM (
    SELECT amount FROM fin_settlement
    WHERE kind = 'RECEIPT' AND status = 'APPROVED' AND settle_date >= #{begin} AND settle_date <= #{end}
    UNION ALL
    SELECT amount FROM fin_advance
    WHERE kind = 'RECEIPT' AND advance_date >= #{begin} AND advance_date <= #{end}
) t

SELECT u.nickname AS "name", t.amount AS "amount", t.orders AS "orders"
FROM (
    SELECT salesman_id, SUM(total_amount) AS amount, COUNT(*) AS orders
    FROM scm_order
    WHERE kind = 'SALES' AND status IN ('APPROVED', 'PARTIAL', 'COMPLETED') AND order_date >= #{begin} AND order_date <= #{end}
    GROUP BY salesman_id
) t
LEFT JOIN sys_user u ON u.id = t.salesman_id
ORDER BY t.amount DESC
LIMIT #{limit}
